local function clamp(v, lo, hi)
    return math.min(
        hi,
        math.max(lo, v)
    )
end
local function lerp(a, b, u)
    return a + (b - a) * u
end
local function smooth(a, b, t)
    local u = clamp((t - a) / (b - a), 0, 1)
    return u * u * (3 - 2 * u)
end
local function hash(n)
    local s = math.sin(n * 127.1 + 311.7) * 43758.5453
    return s - math.floor(s)
end
local function col(c, alphaMul)
    return Color(
        c.r,
        c.g,
        c.b,
        math.floor(c.a * (alphaMul == nil and 1 or clamp(alphaMul, 0, 1)) + 0.5)
    )
end
local function circlePts(cx, cy, r, seg)
    local pts = {}
    do
        local i = 0
        while i < seg do
            local a = i / seg * math.pi * 2
            pts[#pts + 1] = Vec2(
                cx + math.cos(a) * r,
                cy + math.sin(a) * r
            )
            i = i + 1
        end
    end
    return pts
end
local function ring(d, cx, cy, r, seg, w, c, a0, a1)
    local from = a0 == nil and 0 or a0
    local to = a1 == nil and math.pi * 2 or a1
    local px = cx + math.cos(from) * r
    local py = cy + math.sin(from) * r
    do
        local i = 1
        while i <= seg do
            local ang = from + (to - from) * i / seg
            local nx = cx + math.cos(ang) * r
            local ny = cy + math.sin(ang) * r
            d:drawSegment(
                Vec2(px, py),
                Vec2(nx, ny),
                w,
                c
            )
            px = nx
            py = ny
            i = i + 1
        end
    end
end
local function rectPts(x, y, w, h)
    return {
        Vec2(x, y),
        Vec2(x + w, y),
        Vec2(x + w, y + h),
        Vec2(x, y + h)
    }
end
local function sectorPts(cx, cy, r, a0, a1, seg)
    local pts = {Vec2(cx, cy)}
    do
        local i = 0
        while i <= seg do
            local a = a0 + (a1 - a0) * i / seg
            pts[#pts + 1] = Vec2(
                cx + math.cos(a) * r,
                cy + math.sin(a) * r
            )
            i = i + 1
        end
    end
    return pts
end
