        bubLb:addTo(root)
        bubLb.visible = false
    end
    local function ridgeY(wx, base, amp, seed)
        return base + amp * (0.55 * math.sin(wx * 0.0042 + seed) + 0.3 * math.sin(wx * 0.0113 + seed * 2.1) + 0.15 * math.sin(wx * 0.027 + seed * 0.7))
    end
    local function drawRidge(d, base, amp, seed, drift, c)
        local pts = {}
        do
            local x = -W / 2 - 60
            while x <= W / 2 + 60 do
                pts[#pts + 1] = Vec2(
                    x,
                    ridgeY(x + drift, base, amp, seed)
                )
                x = x + 48
            end
        end
        pts[#pts + 1] = Vec2(W / 2 + 60, -H / 2 - 80)
        pts[#pts + 1] = Vec2(-W / 2 - 60, -H / 2 - 80)
        d:drawPolygon(pts, c)
    end
    local function drawTown(d, c)
        local y0 = -H / 2 + 96
        local pts = {Vec2(-W / 2 - 40, y0)}
        local x = -W / 2 - 20
        local i = 0
        while x < 40 do
            local w = 64 + hash(i * 5.7) * 26
            local hgt = 22 + hash(i * 3.1) * 18
            pts[#pts + 1] = Vec2(x + w * 0.5, y0 + hgt)
            pts[#pts + 1] = Vec2(x + w, y0 + 6)
            x = x + w
            i = i + 1
        end
        pts[#pts + 1] = Vec2(x, -H / 2 - 80)
        pts[#pts + 1] = Vec2(-W / 2 - 40, -H / 2 - 80)
        d:drawPolygon(pts, c)
        d:drawPolygon(
            rectPts(-W / 2 + 34, y0 + 6, 30, 74),
            c
        )
        d:drawPolygon(
            {
                Vec2(-W / 2 + 24, y0 + 80),
                Vec2(-W / 2 + 74, y0 + 80),
                Vec2(-W / 2 + 49, y0 + 104)
            },
            c
        )
    end
