    local function drawBubble(d, a)
        if a <= 0.01 then
            return
        end
        local bw = 170
        local bh = 58
        local x0 = BUBX - bw / 2
        local y0 = BUBY - bh / 2
        local r = 10
        local fill = col(Palette.paper, a)
        local outline = col(Palette.inkDark, a)
        d:drawPolygon(
            rectPts(x0, y0, bw, bh),
            fill
        )
        local border = {
            Vec2(x0, y0 + r),
            Vec2(x0 + r, y0),
            Vec2(x0 + bw - r, y0),
            Vec2(x0 + bw, y0 + r),
            Vec2(x0 + bw, y0 + bh - r),
            Vec2(x0 + bw - r, y0 + bh),
            Vec2(x0 + r, y0 + bh),
            Vec2(x0, y0 + bh - r),
            Vec2(x0, y0 + r)
        }
        do
            local i = 0
            while i < #border - 1 do
                d:drawSegment(border[i + 1], border[i + 1 + 1], 2.5, outline)
                i = i + 1
            end
        end
        d:drawPolygon(
            {
                Vec2(BUBX - 26, y0 + 1),
                Vec2(BUBX - 2, y0 + 1),
                Vec2(BUBX - 18, y0 - 20)
            },
            fill
        )
        d:drawSegment(
            Vec2(BUBX - 26, y0 + 1),
            Vec2(BUBX - 18, y0 - 20),
            2.5,
            outline
        )
        d:drawSegment(
            Vec2(BUBX - 18, y0 - 20),
            Vec2(BUBX - 2, y0 + 1),
            2.5,
            outline
        )
